def get_precomputed_road_geometry(origin: str, destination: str):
    if not origin or not destination:
        return None
    fwd = f"{origin}_{destination}"
    rev = f"{destination}_{origin}"
    if fwd in PRECOMPUTED_ROAD_GEOMETRIES:
        return PRECOMPUTED_ROAD_GEOMETRIES[fwd]["coordinates"]
    if rev in PRECOMPUTED_ROAD_GEOMETRIES:
        return list(reversed(PRECOMPUTED_ROAD_GEOMETRIES[rev]["coordinates"]))
    return None
